[/^Code ([A-Z0-9]{8})\. Einträge stammen von den Werkstätten\. Keine Daten über Besitzer\. Fehlt eine Diebstahlmeldung, ist das kein Beweis\.$/,(m,c)=>`Code ${c}. Entries come from workshops. No data about owners. A missing theft report is not proof.`],
[/^FYF-Abgleich: kein Treffer in unserer Rückrufliste \(Stand ([\d.]+)\)\. Die Liste ist nicht vollständig – offizielle Quellen oben trotzdem prüfen\.$/,(m,d)=>`FYF check: no match in our recall list (as of ${d}). The list is not complete – still check the official sources above.`],
[/^Anonyme Laufleistungen anderer FYF-Pässe mit dem gleichen Modell \((.+)\)\. Angezeigt erst ab 5 Rädern\.$/,(m,a)=>`Anonymous mileages of other FYF passes with the same model (${a}). Shown from 5 bikes upwards.`],
[/^„(.+) Rückruf“ suchen$/,(m,a)=>`Search “${a} recall”`],
[/^Bei (.+) anfragen$/,(m,a)=>`Request at ${a}`],
[/^Nächste freie Termine bei (.+):$/,(m,a)=>`Next free slots at ${a}:`],
[/^Status: (.+)$/,(m,a)=>`Status: ${T(a)||a}`],
[/^Fällig: (.+)$/,(m,a)=>`Due: ${a}`],
[/^(\d+) Punkte?$/,(m,a)=>`${a} item${a==='1'?'':'s'}`],
[/^Von Werkstätten eingetragen \((\d+)\)$/,(m,a)=>`Entered by workshops (${a})`]
