function T(s){ if(D[s]!=null) return D[s]; for(const [re,f] of P){ const m=s.match(re); if(m) return f(...m); } return null; }
function tr(node){ const raw=node.nodeValue; if(!raw||!/[A-Za-zÄÖÜäöüß]/.test(raw)) return; const t=raw.replace(/\s+/g,' ').trim(); const x=T(t); if(x!=null&&x!==t){ const lead=raw.match(/^\s*/)[0], tail=raw.match(/\s*$/)[0]; node.nodeValue=lead+x+tail; } }
function trEl(el){ ['placeholder','aria-label','title'].forEach(a=>{ const v=el.getAttribute&&el.getAttribute(a); if(v){ const x=T(v.trim()); if(x!=null) el.setAttribute(a,x); } }); }
